type SendResult = { ok: true } | { ok: false; retryable: boolean };
type ClaimResult = 'acquired' | 'delivered' | 'busy';
type StoredStatus = 'delivered' | 'failed';

interface Provider {
  send(recipient: string, body: string): Promise<SendResult>;
}
interface IdempotencyStore {
  // claim atomically reserves a key unless it is already delivered or in flight.
  claim(key: string): Promise<ClaimResult>;
  mark(key: string, status: StoredStatus): Promise<void>;
}
interface Notice { key: string; recipient: string; body: string; route: string[]; }
const sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));

class RoutedSender {
  constructor(private providers: Record<string, Provider>, private idempotency: IdempotencyStore) {}

  async send(notice: Notice): Promise<string> {
    const claim = await this.idempotency.claim(notice.key);
    if (claim !== 'acquired') return claim === 'delivered' ? 'delivered' : 'in_flight';

    for (const channel of notice.route) {
      const provider = this.providers[channel];
      if (!provider) continue;
      for (let attempt = 1; attempt <= 2; attempt++) {
        const result = await provider.send(notice.recipient, notice.body);
        if (result.ok) {
          await this.idempotency.mark(notice.key, 'delivered');
          return 'delivered';
        }
        if (!result.retryable) break;
        if (attempt < 2) await sleep(250);
      }
    }

    await this.idempotency.mark(notice.key, 'failed');
    return 'failed';
  }
}
